/// <summary>
/// AVAcountRecordWithRanges
/// </summary>
/// <param name = "_queryRun">QueryRun</param>
/// <returns>Integer</returns>
public client server static Integer AVAcountRecordWithRanges(QueryRun _queryRun)
{
    int recordCount;

    while (_queryRun.next())
    {
        recordCount ++;
    }

    return recordCount;
}
